Perfecto. Juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Tamaño del arreglo: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    int k;
    printf("Posiciones a rotar a la derecha: ");
    scanf("%d", &k);
    k = k % N; /* rotar N veces = no rotar */

    /* Rotar k veces, un paso a la derecha por iteración */
    for (int paso = 0; paso < k; paso++) {
        int temp = arr[N - 1];        /* guardar el último */
        for (int i = N - 2; i >= 0; i--) { /* mover de derecha a izquierda */
            arr[i + 1] = arr[i];
        }
        arr[0] = temp;                /* el último va al principio */
    }

    /* Mostrar resultado */
    printf("\nArreglo rotado %d posición/es a la derecha:\n", k);
    for (int i = 0; i < N; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

El error clásico es intentar mover in-place de izquierda a derecha sin variable temporal — los valores se sobreescriben y se pierden. La variable `temp` y el sentido descendente del loop interno son la solución.
